-- usage in hyprland.lua: require("binds")({ terminal = ..., launcher = ..., launcher_alt = ... })

-- mission control is open (hypr/overview-flag.sh keeps this file while it is)
local function overview_open()
  local f = io.open((os.getenv("XDG_RUNTIME_DIR") or "/tmp") .. "/hymission-open", "r")
  if f then f:close() end
  return f ~= nil
end
-- focus the leftmost window of a desktop, once mission control's desktop switch is done (it takes
-- 180 ms and then focuses that desktop's last-used window itself)
local function focus_leftmost(ws)
  hl.timer(function()
    local best
    for _, w in ipairs(hl.get_workspace_windows(ws) or {}) do
      local x = type(w.at) == "table" and w.at.x or 0
      if not w.hidden and (not best or x < best.x) then best = { x = x, address = w.address } end
    end
    if best then hl.dispatch(hl.dsp.focus({ window = "address:" .. best.address })) end
  end, { timeout = 250, type = "oneshot" })
end

return function(P)
  hl.bind("ALT + 1", hl.dsp.focus({ workspace = 1 })) -- desktop.goto.1
  hl.bind("ALT + 2", hl.dsp.focus({ workspace = 2 })) -- desktop.goto.2
  hl.bind("ALT + 3", hl.dsp.focus({ workspace = 3 })) -- desktop.goto.3
  hl.bind("ALT + 4", hl.dsp.focus({ workspace = 4 })) -- desktop.goto.4
  hl.bind("ALT + 5", hl.dsp.focus({ workspace = 5 })) -- desktop.goto.5
  hl.bind("SUPER + SHIFT + code:192", function() local id = (hl.get_active_workspace() or {}).id or 1; local n = (id - 1 - 1) % 5 + 1; hl.dispatch(hl.dsp.focus({ workspace = n })); if overview_open() then focus_leftmost(n) end end) -- desktop.prev
  hl.bind("SUPER + code:192", function() local id = (hl.get_active_workspace() or {}).id or 1; local n = (id - 1 + 1) % 5 + 1; hl.dispatch(hl.dsp.focus({ workspace = n })); if overview_open() then focus_leftmost(n) end end) -- desktop.next
  hl.bind("ALT + SHIFT + 1", hl.dsp.window.move({ workspace = 1, follow = false })) -- desktop.move.1
